import CoreGraphics

// MARK: - Japan Prefecture Map Shapes
//
// v4 LEGAL-SAFE MAP DATA REPLACEMENT (2026-09-11), v5 RENDER QUALITY PASS
// (2026-09-11)
//
// データ出典: Natural Earth (https://www.naturalearthdata.com),
// dataset: ne_10m_admin_1_states_provinces (1:10m Cultural Vectors,
// "Admin 1 – States, Provinces"), version: バンドルされた
// nvkelso/natural-earth-vector公式ミラー(Natural Earthの技術リード
// Nathaniel Vaughn Kelso本人が管理するGitHubミラー)の`master`ブランチ
// 時点のスナップショットを2026-09-11に取得(このファイルの生成日時が
// 実質的なバージョン識別子。個別のgit commit hashは記録していない)。
// Source URL: https://github.com/nvkelso/natural-earth-vector/blob/master/geojson/ne_10m_admin_1_states_provinces.geojson
// License status: Natural Earth公式Terms of Use
// (https://www.naturalearthdata.com/about/terms-of-use/)に
// "All versions of Natural Earth raster + vector map data found on
// this website are in the public domain... No permission is needed
// to use Natural Earth. Crediting the authors is unnecessary."と明記。
// → アプリ内creditは法的に必須ではない(ライセンス文面上「unnecessary」と
// 明記されているため、必須かどうかを推測ではなくこの一次情報で判断した)。
// 誠実さの観点でこのコードコメントには出典を残す。
//
// 変換パイプライン(このファイル自体はSwiftのみ、変換はPython、
// 生成物のみコミット):
// 1. 各都道府県のPolygon/MultiPolygonから外周リングのみを抽出(穴/内陸湖は無視)。
// 2. 主要な陸地(面積最大のリング)は必ず採用。付随する離島リングは
//    「面積が主要陸地の1%以上」かつ「重心が主要陸地から3.0度以内」の
//    ものだけ採用(極小離島ノイズを避けつつ、佐渡・淡路・隠岐・
//    伊豆大島・八丈島・対馬・壱岐・五島列島・種子島・屋久島・奄美大島等の
//    主要な有人島は残す、データを捏造しない機械的な基準)。沖縄県のみ、
//    本土から大きく離れるため独自クラスタとして下記IIで別処理。
// 3. 等距円筒図法+緯度36度でのcos補正(x = lon * cos(36°), y = -lat)で
//    経緯度を投影(実際の相対形状・相対面積をそのまま保持する投影方式)。
// 4. Ramer-Douglas-Peucker法で座標点数を削減(新しい地理情報は生成せず、
//    既存頂点の間引きのみ)。47都道府県本土は平均47.6点/県(最小21点・
//    最大59点)で、iPhone実機のHome表示サイズ(地図幅約310〜360pt)に
//    対して過剰でも過疎でもない密度であることをv5監査で確認済み
//    (「レンダリングがPathの集合に見える」問題の主因は点密度ではなく
//    stroke styleだった、詳細はPictriJapanCollectionMap.swift参照)。
// 5. 間引き後に自己交差が残る場合のみ、2-opt polygon untangling
//    (既存`QuestPrefectureGeometry`と同一アルゴリズム)を適用。
// 6. 全ポリゴンをキャンバス座標(下記canvasWidth/canvasHeight)へ
//    一律スケール変換。
// 7. v5追加: 離島は「Home表示スケールで判別できる最小サイズ」
//    (キャンバス座標での外接矩形対角線2.0pt未満)を下回るものを除外した
//    (本土幅312pt換算で対角線2pt未満は実機で事実上1px未満になり、
//    「地図として重要な情報」ではなく「視覚ノイズ」と判断。座標の捏造や
//    追加ではなく、既に投影済みの実データから小さすぎるものを間引いた
//    だけ)。沖縄離島群は17→7、長崎離島群は10→9に整理された。
//
// II. 沖縄インセット: 沖縄県の本島+離島群は、本土と同じ投影を
// 適用した後、形状・相対配置はそのまま(捏造・歪曲なし)、全体をまとめて
// 均一スケール+平行移動だけでキャンバス右下の専用領域へ配置している
// (国土地理院の全国地図等でも広く使われる、沖縄を本土から数百km引き寄せて
// 別枠表示する標準的な地図表現。座標を歪めているのではなく、独立した
// クラスタとして再配置しているだけ)。
struct QuestPrefectureShape: Identifiable {
    let id: String
    let name: String
    let region: String
    let points: [CGPoint]
}

/// 都道府県本土から離れた有人島(佐渡・淡路・隠岐・伊豆大島・対馬・五島列島・
/// 種子島・屋久島・奄美大島・沖縄離島群 等)。`questPrefectureShapes`本体
/// (各県1エントリ、本土のみ)とは別配列にすることで、既存の`$0.id == ...`
/// 系ルックアップ(CameraView/MemoriesView/MapView/QuestAreaResolver等)に
/// 一切影響を与えない。`prefectureId`で親県のvisited状態・色を共有する。
struct QuestPrefectureIslandShape: Identifiable {
    let id: String
    let prefectureId: String
    let points: [CGPoint]
}

